#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include "Halide.h"

// include common definitions (DATA_TYPE, N, etc.)
#include "defines.hpp"

// include benchmark-specific definitions
#include "lu.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

// -----------------------------------------------------------------------------
// Array initialization: translate Polybench init_array() into a Halide pipeline
// -----------------------------------------------------------------------------
static void init_array(int n, Halide::Buffer<num_t, 2> A) {
    // We map the original C array A[i][j] to Halide buffer A(j, i):
    //   - i is the row index    -> second dimension (y)
    //   - j is the column index -> first dimension (x)

    Var i("i"), j("j");
    Func A0("A0"), B("B");

    // First, generate the lower-triangular matrix used as in the C code:
    //
    // for (i = 0; i < n; i++) {
    //   for (j = 0; j <= i; j++)
    //     A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
    //   for (j = i+1; j < n; j++)
    //     A[i][j] = 0;
    //   A[i][i] = 1;
    // }
    //
    // Note: for 0 <= j < n, (-j % n) == -j, so we can drop the % n.
    // We fold all this into a single expression and let Halide
    // generate the loops.

    Expr one   = cast<num_t>(Expr(1));
    Expr zero  = cast<num_t>(Expr(0));
    Expr n_val = cast<num_t>(Expr(n));

    // A0(j, i) corresponds to A[i][j] in the original C code.
    A0(j, i) = select(
        j <= i,
        // On or below the diagonal
        select(i == j,
               // Diagonal element
               one,
               // Strictly lower triangular part
               cast<num_t>(Expr(-1) * j) / n_val + one),
        // Above the diagonal
        zero);

    // Now make the matrix positive semi-definite by computing:
    //
    // B[r][s] = sum_t A[r][t] * A[s][t];
    //
    // and then copying B back into A. In terms of our mapping:
    // B(r, s) in C  -> B(j, i) in Halide
    // A[r][t]       -> A0(t, r) -> A0(t, i)
    // A[s][t]       -> A0(t, s) -> A0(t, j)
    //
    // So:
    //   B(j, i) = sum_{t=0..n-1} A0(t, i) * A0(t, j)

    RDom t(0, n, "t");
    B(j, i) = cast<num_t>(Expr(0));
    B(j, i) += A0(t, i) * A0(t, j);

    // -----------------------------------------------------------------
    // Schedule for initialization:
    //
    //  - Compute B at the root so we can schedule both the pure and
    //    update definitions explicitly.
    //  - Parallelize across rows (i) to improve multicore utilization.
    //  - Vectorize across columns (j) to improve SIMD utilization.
    //  - For the reduction update, reorder so that the innermost
    //    loop is over the reduction variable 't' and the next inner
    //    loop over 'j', which is vectorized.
    // -----------------------------------------------------------------
    const int vec_width = 8;  // Reasonable fixed SIMD width on modern x86

    B.compute_root()
        .parallel(i)
        .vectorize(j, vec_width);

    RVar t_r = t.x;
    B.update()
        .reorder(t_r, j, i)   // inner -> outer: t, j, i  => loops: for i, for j, for t
        .parallel(i)
        .vectorize(j, vec_width);

    // Realize B directly into the provided buffer A. This is equivalent
    // to computing B and then copying B into A as in the original C code.
    B.realize(A);
}

// -----------------------------------------------------------------------------
// Main
// -----------------------------------------------------------------------------
int main(int argc, char *argv[]) {
    // Problem size
    int n = N;

    // Matrix A: original C is DATA_TYPE A[N][N];
    // We map to Halide Buffer with shape (cols, rows) = (n, n)
    Halide::Buffer<num_t, 2> A(n, n);

    // Initialize A (PSD lower-triangular gram matrix)
    init_array(n, A);

    // -------------------------------------------------------------------------
    // Translate kernel_lu into Halide-assisted code.
    //
    // Original C kernel:
    //
    // for (i = 0; i < n; i++) {
    //   for (j = 0; j < i; j++) {
    //     for (k = 0; k < j; k++) {
    //       A[i][j] -= A[i][k] * A[k][j];
    //     }
    //     A[i][j] /= A[j][j];
    //   }
    //   for (j = i; j < n; j++) {
    //     for (k = 0; k < i; k++) {
    //       A[i][j] -= A[i][k] * A[k][j];
    //     }
    //   }
    // }
    //
    // This algorithm has loop-carried dependencies along i and j, so we cannot
    // express the full kernel as a single pure Halide Func. Instead, we:
    //
    //   - Keep the outer loops over i and j on the host (as required to
    //     preserve the sequential dependencies).
    //   - Use Halide Funcs to compute each inner summation over k:
    //       sum_{k<j} A[i][k] * A[k][j]  (for j < i, the "L" part)
    //       sum_{k<i} A[i][k] * A[k][j]  (for j >= i, the "U" part)
    //
    //   - For numerical work inside the kernel we build small Halide
    //     pipelines (dot products) and reuse them many times.
    //
    // Optimization vs. the original version:
    //
    //   * The first inner loop (j < i) is still handled one (i, j)
    //     at a time, but we now reuse the scalar output buffer for
    //     the Halide pipeline to avoid repeated allocations.
    //
    //   * The second inner loop (j >= i) has *no* loop-carried
    //     dependencies in j, so we express the entire row update for
    //     fixed i as a 1D Halide Func and compute all A[i][j] for
    //     j >= i in one realization. This greatly improves data
    //     locality and amortizes the JIT-call overhead.
    // -------------------------------------------------------------------------

    // ImageParam representing the current matrix A; note that we never write
    // to A inside Halide; we only read from it in the Funcs below. The
    // in-place updates to A are done on the host after each realization.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    A_param.set(A);

    // Scalar parameters for the current indices and offsets
    Param<int> i_param("i");
    Param<int> j_param("j");      // used in the "L" part
    Param<int> offset_param("offset");  // base column for the "U" row update

    // -----------------------------------------------------------------------------
    // Func to compute A[i][j] - sum_{k=0}^{j-1} A[i][k] * A[k][j]
    // for the case j < i (the "L" part), before dividing by A[j][j].
    // We express this as a scalar Func (zero-dimensional).
    // -----------------------------------------------------------------------------
    Func left_elem("left_elem");
    {
        // A[i][j] in C corresponds to A_param(j_param, i_param) in Halide
        left_elem() = A_param(j_param, i_param);

        // Sum over k = 0 .. j-1:
        // A[i][j] -= A[i][k] * A[k][j]
        //
        // Mapping:
        //   A[i][k] -> A_param(k, i_param)
        //   A[k][j] -> A_param(j_param, k)
        RDom k_left(0, j_param, "k_left");
        Expr neg_one = cast<num_t>(Expr(-1));
        left_elem() += neg_one *
                       A_param(k_left, i_param) *
                       A_param(j_param, k_left);

        // For a 0-D Func, the default schedule is sufficient; no
        // explicit vectorization is needed here.
        left_elem.compute_root();
    }

    // -----------------------------------------------------------------------------
    // Func to compute the entire "U" part for a fixed row i in one shot:
    //
    //   for (j = i; j < n; j++) {
    //     A[i][j] -= sum_{k=0}^{i-1} A[i][k] * A[k][j];
    //   }
    //
    // For fixed i, A[i][k] (k < i) are already computed and are not
    // modified in this loop, and A[k][j] (k < i) belong to previous
    // rows, so there are no dependencies across j. This means we can
    // safely compute the whole row in parallel/vectorized fashion
    // using a single Func and a 1D realization.
    // -----------------------------------------------------------------------------
    Var jj("jj"); // column index for the row-relative coordinate
    Func row_update("row_update");

    // row_update(jj) computes A[i][j] - sum_{k=0}^{i-1} A[i][k] * A[k][j]
    // where j = offset_param + jj and (for our usage) offset_param == i.
    {
        // Base value A[i][j]
        row_update(jj) = A_param(offset_param + jj, i_param);

        // Reduction over k = 0..i-1:
        RDom k_u(0, i_param, "k_u");
        Expr neg_one = cast<num_t>(Expr(-1));

        row_update(jj) += neg_one *
                          A_param(k_u, i_param) *
                          A_param(offset_param + jj, k_u);

        // Schedule for row_update:
        //
        //  - Compute at root; we will realize it repeatedly for each i.
        //  - Vectorize across jj (columns within the row) to exploit
        //    SIMD parallelism. The reduction is over k_u; we reorder
        //    so that the pure variable jj is the innermost loop.
        const int vec_width = 8;

        row_update.compute_root();

        RVar k_u_r = k_u.x;
        row_update.update()
            .reorder(jj, k_u_r)   // inner -> outer: jj, k => loops: for k, for jj
            .vectorize(jj, vec_width);
    }

    // JIT-compile the pipelines once; we will reuse them for all (i, j).
    left_elem.compile_jit();
    row_update.compile_jit();

    // Reuse a scalar Buffer for left_elem to avoid repeated allocations.
    Halide::Buffer<num_t> tmp_left;
    // First call allocates the storage; we discard the initial value.
    left_elem.realize(tmp_left);

    // For the row-update part, we will allocate a 1D buffer of length n
    // once and then crop it to the desired length (n - i) for each row,
    // so we allocate only once.
    Halide::Buffer<num_t> row_vals_full(n);

    // -------------------------------------------------------------------------
    // Run kernel and time it
    // -------------------------------------------------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    for (int i = 0; i < n; i++) {
        i_param.set(i);

        // ---------------------------------------------------------------------
        // First inner loop: j = 0 .. i-1  (lower triangular "L" part)
        // ---------------------------------------------------------------------
        for (int j = 0; j < i; j++) {
            j_param.set(j);

            // Compute A[i][j] - sum_{k<j} A[i][k] * A[k][j]
            left_elem.realize(tmp_left);
            num_t val = tmp_left();  // zero-dimensional buffer

            // Divide by A[j][j]
            // Mapping: A[j][j] in C -> A(j, j) in Halide
            val /= A(j, j);

            // Store back into A[i][j] (i.e. A(j, i) in Halide)
            A(j, i) = val;
        }

        // ---------------------------------------------------------------------
        // Second inner loop: j = i .. n-1  (upper triangular "U" part)
        //
        // Here there are no dependencies between different j, so we use
        // the 1D Halide Func row_update to compute all A[i][j] for
        // j >= i in one realization for better locality and efficiency.
        // ---------------------------------------------------------------------
        {
            const int length = n - i;
            if (length > 0) {
                offset_param.set(i);

                // Crop the pre-allocated buffer to the current active length.
                Halide::Buffer<num_t> row_vals =
                    row_vals_full.cropped(0, 0, length);

                // Realize row_update(jj) for jj = 0 .. length-1
                row_update.realize(row_vals);

                // Copy the results back into A:
                //   j = i + jj
                //   A[i][j] in C -> A(j, i) in Halide
                for (int jj_idx = 0; jj_idx < length; ++jj_idx) {
                    int j = i + jj_idx;
                    A(j, i) = row_vals(jj_idx);
                }
            }
        }
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // -------------------------------------------------------------------------
    // Optional: print the resulting matrix, in the same order as the C version
    // -------------------------------------------------------------------------
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                // A[i][j] in C corresponds to A(j, i) in Halide
                std::cerr << A(j, i) << '\n';
            }
        }
    }

    // Print timing (in seconds)
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
