    //
    // B[r][s] = sum_t A[r][t] * A[s][t];
    //
    // and then copying B back into A. In terms of our mapping:
    // B(r, s) in C  -> B(j, i) in Halide
    // A[r][t]       -> A0(t, r) -> A0(t, i)
    // A[s][t]       -> A0(t, s) -> A0(t, j)
    //
    // So:
    //   B(j, i) = sum_{t=0..n-1} A0(t, i) * A0(t, j)

    RDom t(0, n, "t");
    B(j, i) = cast<num_t>(0);
    B(j, i) += A0(t, i) * A0(t, j);

    // -----------------------------
    // Scheduling for initialization
    // -----------------------------
    // This is an O(n^3) matrix multiply; good scheduling matters.
    // We:
    //   - compute B at the root;
    //   - parallelize across rows (i);
    //   - vectorize across columns (j);
    // A0 is left inlined: it is cheap and avoids an extra n^2 buffer.
    Target init_target = get_host_target();
    const int vec = init_target.natural_vector_size(type_of<num_t>());

    B.compute_root()
        .parallel(i)          // distribute rows across threads
        .vectorize(j, vec);   // SIMD over contiguous columns

    // Also vectorize the update (reduction) step over j for better throughput.
    B.update()
        .parallel(i)
        .vectorize(j, vec);

