    // to A through Halide; we only read from it in the Funcs below.
    // In-place updates to A are done on the host (and by realizing
    // into views of A), and are immediately visible to A_param
    // because it points at the same underlying memory.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    A_param.set(A);

    // Scalar parameters for the current (i, j) indices
    Param<int> i_param("i");
    Param<int> j_param("j");

    // -------------------------------------------------------------------------
    // 1) "L" part: scalar Func for
    //       A[i][j] - sum_{k=0}^{j-1} A[i][k] * A[k][j]
    //     used when j < i, followed by division by A[j][j].
    // -------------------------------------------------------------------------
    Func left_elem("left_elem");
    {
        // A[i][j] in C corresponds to A_param(j_param, i_param)
        left_elem() = A_param(j_param, i_param);

        // Sum over k = 0 .. j-1:
        // A[i][j] -= A[i][k] * A[k][j]
        //
        // A[i][k] -> A_param(k_left, i_param)
        // A[k][j] -> A_param(j_param, k_left)
        RDom k_left(0, j_param, "k_left");
        left_elem() += cast<num_t>(-1) *
                       A_param(k_left, i_param) *
                       A_param(j_param, k_left);
    }

    // -------------------------------------------------------------------------
    // 2) "U" part: vector Func for
    //       A[i][j] - sum_{k=0}^{i-1} A[i][k] * A[k][j]
    //     for all j in [i, n). This part has no loop-carried dependency
    //     across j, so we can compute the whole row segment in one
    //     Halide pipeline, improving locality and enabling SIMD.
    // -------------------------------------------------------------------------
    Func upper_row("upper_row");
    Var jj("jj");

    // Logical column index j in the original matrix: j = i_param + jj
    Expr j_index = jj + i_param;

    // Seed with the current matrix entry A[i][j]
    upper_row(jj) = A_param(j_index, i_param);

    // Reduction over k = 0 .. i-1:
    // A[i][j] -= A[i][k] * A[k][j]
    RDom k_right(0, i_param, "k_right");
    upper_row(jj) += cast<num_t>(-1) *
                     A_param(k_right, i_param) *
                     A_param(j_index, k_right);

    // ------------------------
    // Scheduling for LU kernel
    // ------------------------
    Target kernel_target = get_host_target();
    const int vec_lu = kernel_target.natural_vector_size(type_of<num_t>());

    // left_elem is scalar (0-D); there is no meaningful tiling or
    // vectorization to apply. We just JIT-compile it once.
    left_elem.compile_jit(kernel_target);

    // For upper_row (1-D + reduction):
    //   - compute at root;
    //   - vectorize across jj both in pure and update definitions.
    upper_row
        .compute_root()
        .vectorize(jj, vec_lu);
    upper_row
        .update()
        .vectorize(jj, vec_lu);
    upper_row.compile_jit(kernel_target);

    // -------------------------------------------------------------------------
    // Run kernel and time it
    // -------------------------------------------------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    for (int i = 0; i < n; i++) {
        // First inner loop: j = 0 .. i-1  (lower-triangular "L" part)
        for (int j = 0; j < i; j++) {
            i_param.set(i);
            j_param.set(j);

            // Compute A[i][j] - sum_{k<j} A[i][k] * A[k][j]
            Halide::Buffer<num_t> tmp = left_elem.realize();
            num_t val = tmp();  // zero-dimensional buffer

            // Divide by A[j][j]
            // Mapping: A[j][j] in C -> A(j, j) in Halide
            val /= A(j, j);

            // Store back into A[i][j] (i.e. A(j, i) in Halide)
            A(j, i) = val;
        }

        // Second inner loop: j = i .. n-1  (upper-triangular "U" part)
        //
        // This phase has no dependency across j for a fixed i, so we can
        // compute the entire row segment in one vectorized Halide call.
        i_param.set(i);

        int cols = n - i;
        if (cols > 0) {
            // Create a 1D view into A that aliases the row segment:
            //
            //   row i, columns [i .. n-1]
            //
            // Remember: A(col, row) in Halide, so A(i, i) is the first
            //   element of that segment, and dimension 0 (columns) is
            //   contiguous in memory by default.
            //
            // This avoids allocating a temporary buffer and an extra copy:
            // upper_row will write its results directly into A.
            Halide::Buffer<num_t> row_view(&A(i, i), cols);

            // Realize upper_row into this row segment:
            //
            //   For jj in [0 .. cols-1]:
            //     j_index = i + jj
            //     row_view(jj) =
            //       A[i][j_index] - sum_{k=0}^{i-1} A[i][k] * A[k][j_index]
            //
            // which exactly matches the original C code for j in [i, n).
            upper_row.realize(row_view);
        }
    }

    auto end      = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // -------------------------------------------------------------------------
    // Optional: print the resulting matrix, in the same order as the C version
    // -------------------------------------------------------------------------
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                // A[i][j] in C corresponds to A(j, i) in Halide
                std::cerr << A(j, i) << '\n';
            }
        }
    }

    // Print timing (in seconds)
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
