    Expr one   = cast<num_t>(1);
    Expr zero  = cast<num_t>(0);
    Expr n_val = cast<num_t>(n);

    // -------------------------------------------------------------------------
    // Step 1: build the lower-triangular matrix A0, matching the C code:
    //
    // for (i = 0; i < n; i++) {
    //   for (j = 0; j <= i; j++)
    //     A[i][j] = (DATA_TYPE)(-j % n) / n + 1;  // but (-j % n) == -j for 0<=j<n
    //   for (j = i+1; j < n; j++)
    //     A[i][j] = 0;
    //   A[i][i] = 1;
    // }
    //
    // In Halide coordinates (x=j, y=i):
    //   A0(j, i) is:
    //     - 1 on the diagonal
    //     - (-j)/n + 1 for j < i (strictly lower)
    //     - 0 for j > i (upper)
    // -------------------------------------------------------------------------
    A0(j, i) = select(
        j <= i,
        select(i == j,
               one,                         // diagonal
               cast<num_t>(-j) / n_val + one), // strictly lower triangular part
        zero                               // above diagonal
    );

    // -------------------------------------------------------------------------
    // Step 2: make the matrix positive semi-definite:
    //
    // B[r][s] = sum_t A0[r][t] * A0[s][t];
    //
    // Using our mapping (C A[r][s] -> Halide A0(s, r)):
    //   B(j, i) = sum_{t=0..n-1} A0(t, i) * A0(t, j)
    // -------------------------------------------------------------------------
    RDom t(0, n, "t");
    B(j, i) = cast<num_t>(0);
    B(j, i) += A0(t, i) * A0(t, j);

    // -------------------------------------------------------------------------
    // Scheduling for init_array
    //
    // We compute B in parallel over rows (i) and vectorize across columns (j),
    // then compute the reduction update in the same way. This preserves the
    // mathematical result but greatly improves CPU utilization and data
    // locality for large N.
    // -------------------------------------------------------------------------
    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // Parallelize rows, vectorize columns
    B.compute_root()
        .parallel(i)
        .vectorize(j, vec_width);

    // Same strategy for the reduction update: each (i,j) pair is independent
    // with respect to t, so we can parallelize and vectorize over (i,j).
    B.update()
        .parallel(i)
        .vectorize(j, vec_width);

    // Realize B directly into the provided buffer A. This is equivalent
    // to computing B and then copying B into A as in the original C code.
    B.realize(A);
}

// -----------------------------------------------------------------------------
// Main
// -----------------------------------------------------------------------------
int main(int argc, char *argv[]) {
    // Problem size
    int n = N;

    // Matrix A: original C is DATA_TYPE A[N][N];
    // We map to Halide Buffer with shape (cols, rows) = (n, n)
    Halide::Buffer<num_t, 2> A(n, n);

    // Initialize A using the Halide pipeline above
    init_array(n, A);

    // -------------------------------------------------------------------------
    // Translate kernel_lu into Halide-assisted code.
    //
    // Original C kernel:
    //
    // for (i = 0; i < n; i++) {
    //   for (j = 0; j < i; j++) {
    //     for (k = 0; k < j; k++) {
    //       A[i][j] -= A[i][k] * A[k][j];
    //     }
    //     A[i][j] /= A[j][j];
    //   }
    //   for (j = i; j < n; j++) {
    //     for (k = 0; k < i; k++) {
    //       A[i][j] -= A[i][k] * A[k][j];
    //     }
    //   }
    // }
    //
    // This algorithm has loop-carried dependencies along i and j, so we cannot
    // express the full kernel as a single pure Halide Func. Instead, we:
    //
    //   - Keep the outer loops over i and the left-looking j-loop on the host
    //     (as required to preserve the sequential dependencies).
    //   - Use Halide Funcs to compute the inner reductions over k.
    //   - For the j < i case (L factor), we still compute a scalar per (i,j)
    //     using a tiny Halide reduction.
    //   - For the j >= i case (U factor), we exploit the fact that, for a fixed
    //     i, all columns j >= i are independent and can be computed as a
    //     single 1-D Halide pipeline over j. This greatly reduces per-element
    //     JIT overhead and enables vectorization across j.
    // -------------------------------------------------------------------------

    // ImageParam representing the current matrix A; we only read from it
    // inside Halide. In-place updates to A are done on the host, and since the
    // ImageParam holds a reference to the same buffer, the updates are visible
    // to subsequent Halide evaluations.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    A_param.set(A);

    // Scalar parameters for the current indices
    Param<int> i_param("i");
    Param<int> j_param("j");

    // -------------------------------------------------------------------------
    // Func to compute:
    //   left_elem(i,j) = A[i][j] - sum_{k=0}^{j-1} A[i][k] * A[k][j]
    //
    // for the case j < i (the "L" part), before dividing by A[j][j].
    //
    // Mapping to Halide coordinates (A[i][j] -> A_param(j, i)):
    //   A[i][j]     -> A_param(j_param, i_param)
    //   A[i][k]     -> A_param(k_left,   i_param)
    //   A[k][j]     -> A_param(j_param, k_left)
    // -------------------------------------------------------------------------
    Func left_elem("left_elem");
    {
        Expr minus_one = cast<num_t>(-1);

        left_elem() = A_param(j_param, i_param);  // start from A[i][j]

        RDom k_left(0, j_param, "k_left");
        left_elem() += minus_one *
                       A_param(k_left, i_param) *
                       A_param(j_param, k_left);
    }

    // -------------------------------------------------------------------------
    // Func to compute an entire "U" row slice at once:
    //
    //   right_row(i, j) = A[i][j] - sum_{k=0}^{i-1} A[i][k] * A[k][j]
    //                       for all j (we'll only realize j in [i, n-1])
    //
    // For a fixed i, all j >= i are independent: the sum only uses
    //   A[i][k] for k < i   (already computed L entries on row i)
    //   A[k][j] for k < i   (rows < i, fixed before row i starts)
    //
    // There is no dependence on A[i][j] at other j, so we can compute
    // all right_row(j) for j >= i in one Halide call, enabling
    // vectorization and lowering JIT overhead.
    //
    // Mapping again (A[i][j] -> A_param(j, i)):
    //   A[i][j] -> A_param(j, i_param)
    //   A[i][k] -> A_param(k_right, i_param)
    //   A[k][j] -> A_param(j, k_right)
    // -------------------------------------------------------------------------
    Var j_idx("j_idx");
    Func right_row("right_row");
    {
        Expr minus_one = cast<num_t>(-1);

        right_row(j_idx) = A_param(j_idx, i_param);

        RDom k_right(0, i_param, "k_right");
        right_row(j_idx) += minus_one *
                            A_param(k_right, i_param) *
                            A_param(j_idx, k_right);
    }

    // -------------------------------------------------------------------------
    // Schedule the per-row U-factor pipeline for good locality and SIMD
    // -------------------------------------------------------------------------
    Target host_target = get_host_target();
    const int vec_width = host_target.natural_vector_size(type_of<num_t>());

    // right_row is a 1D reduction in j_idx. We compute it at root (per call),
    // and vectorize across j. Each realization will be for a subrange j∈[i,n),
    // controlled via the Buffer we pass to realize().
    right_row
        .compute_root()
        .vectorize(j_idx, vec_width);

    // Vectorize the update over j as well (reduction is over k, so j-lanes
    // are independent).
    right_row.update()
        .vectorize(j_idx, vec_width);

    // JIT-compile the scalar and per-row pipelines once; we will reuse them
    // for all (i, j).
    left_elem.compile_jit(host_target);
    right_row.compile_jit(host_target);

    // -------------------------------------------------------------------------
    // Run kernel and time it
    // -------------------------------------------------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    for (int i = 0; i < n; i++) {
        // -------------------------------
        // First inner loop: j = 0 .. i-1
        // -------------------------------
        for (int j = 0; j < i; j++) {
            i_param.set(i);
            j_param.set(j);

            // Compute A[i][j] - sum_{k<j} A[i][k] * A[k][j]
            // left_elem is a zero-dimensional Func, realized as a scalar.
            Halide::Buffer<num_t> tmp = left_elem.realize();
            num_t val = tmp();  // zero-dimensional buffer

            // Divide by A[j][j]
            // Mapping: A[j][j] in C -> A(j, j) in Halide
            val /= A(j, j);

            // Store back into A[i][j] (i.e. A(j, i) in Halide)
            A(j, i) = val;
        }

        // -----------------------------------------------
        // Second inner loop: j = i .. n-1  (U factor row)
        // -----------------------------------------------
        if (i < n) {
            i_param.set(i);

            // We compute all A[i][j] for j ∈ [i, n-1] at once using right_row.
            // Create a 1D buffer that covers exactly this j-range, with
            // coordinates j = i, i+1, ..., n-1. Setting the minimum to 'i'
            // ensures Halide's realization domain matches the C loop bounds.
            Halide::Buffer<num_t> row_vals(n - i);
            row_vals.set_min(i);

            right_row.realize(row_vals);

            // Copy the computed values back into A[i][j].
            // Mapping: A[i][j] in C -> A(j, i) in Halide
            for (int j = i; j < n; j++) {
                A(j, i) = row_vals(j);
            }
        }
    }

    auto end      = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // -------------------------------------------------------------------------
    // Optional: print the resulting matrix, in the same order as the C version
    // -------------------------------------------------------------------------
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                // A[i][j] in C corresponds to A(j, i) in Halide
                std::cerr << A(j, i) << '\n';
            }
        }
    }

    // Print timing (in seconds)
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
