    //   B(j, i) = sum_{t=0..n-1} A0(t, i) * A0(t, j)

    RDom t(0, n, "t");
    B(j, i) = cast<num_t>(0);
    B(j, i) += A0(t, i) * A0(t, j);

    // -----------------------------------------------------------------
    // Scheduling for init_array:
    //
    //  - Compute B at the root so we can parallelize and vectorize it.
    //  - Parallelize across the outer dimension (rows, i).
    //  - Vectorize across the inner dimension (columns, j).
    //  - Apply the same schedule to the reduction update.
    //
    // Note that A0 is left inlined into B; this avoids storing an extra
    // N x N matrix and keeps additional memory usage below +50%.
    // -----------------------------------------------------------------
    Target target      = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    B.compute_root()
        .parallel(i)
        .vectorize(j, vec_width);

    B.update()
        .parallel(i)
        .vectorize(j, vec_width);

    // Realize B directly into the provided buffer A. This is equivalent
    // to computing B and then copying B into A as in the original C code.
    B.realize(A);
}

// -----------------------------------------------------------------------------
// Main
// -----------------------------------------------------------------------------
int main(int argc, char *argv[]) {
    // Problem size
    int n = N;

    // Matrix A: original C is DATA_TYPE A[N][N];
    // We map to Halide Buffer with shape (cols, rows) = (n, n)
    Halide::Buffer<num_t, 2> A(n, n);

    // Initialize A
