    // 1) Scalar reduction for the "L" part (j < i):
    //
    //     left_elem(i,j) = A[i][j] - sum_{k=0}^{j-1} A[i][k] * A[k][j]
    //
    // Implemented as a zero-dimensional Func that we realize to a scalar.
    // ---------------------------------------------------------------------
    Func left_elem("left_elem");
    {
        // Map A[i][j] in C to A_param(j_param, i_param) in Halide.
        left_elem() = A_param(j_param, i_param);

        // Sum over k = 0 .. j-1:
        // A[i][j] -= A[i][k] * A[k][j]
        //
        // A[i][k] -> A_param(k, i_param)
        // A[k][j] -> A_param(j_param, k)
        RDom r_left(0, j_param, "r_left");
        left_elem() += cast<num_t>(-1) *
                       A_param(r_left, i_param) *
                       A_param(j_param, r_left);

        // Schedule: vectorize the reduction loop over k. Even though the
        // extent is data-dependent (j_param), Halide will generate tail
        // handling for the final partial vector.
        Target target       = get_host_target();
        const int vec_width = target.natural_vector_size(type_of<num_t>());

        left_elem.compute_root();
        left_elem.update()
                 .vectorize(r_left.x, vec_width);
    }

