    // 2) Row-wise reduction for the "U" part (j >= i):
    //
    //     For fixed i, and all j >= i:
    //       right_row(i,j) = A[i][j] - sum_{k=0}^{i-1} A[i][k] * A[k][j]
    //
    // We construct a 1D Func over j for the current row i. This allows
    // Halide to vectorize across columns j and amortizes overhead by
    // computing the entire right-hand part of row i in one realization.
    // ---------------------------------------------------------------------
    Var jv("jv");
    Func right_row("right_row");
    {
        right_row(jv) = A_param(jv, i_param); // A[i][j]

        // Sum over k = 0 .. i-1:
        // A[i][j] -= A[i][k] * A[k][j]
        RDom r_row(0, i_param, "r_row");
        right_row(jv) += cast<num_t>(-1) *
                         A_param(r_row, i_param) *  // A[i][k]
                         A_param(jv, r_row);        // A[k][j]

        // Schedule: vectorize across j for both pure and update steps.
        Target target       = get_host_target();
        const int vec_width = target.natural_vector_size(type_of<num_t>());

        right_row.compute_root();
        right_row.vectorize(jv, vec_width);
        right_row.update().vectorize(jv, vec_width);
    }

    // JIT-compile the pipelines once; we will reuse them for all (i, j).
    {
        Target target = get_host_target();
        left_elem.compile_jit(target);
        right_row.compile_jit(target);
    }

    // Pre-allocate small buffers used for realizations so we avoid
    // repeated tiny allocations inside the hot loops.
    Halide::Buffer<num_t> left_scalar;  // 0-D scalar buffer
    Halide::Buffer<num_t> row_buffer;   // 1-D buffer for a row segment

    // -------------------------------------------------------------------------
    // Run kernel and time it
    // -------------------------------------------------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    for (int i = 0; i < n; i++) {
        // First inner loop: j = 0 .. i-1   (compute L(i,j))
        for (int j = 0; j < i; j++) {
            i_param.set(i);
            j_param.set(j);

            // Compute A[i][j] - sum_{k<j} A[i][k] * A[k][j]
            left_elem.realize(left_scalar);
            num_t val = left_scalar();  // zero-dimensional buffer

            // Divide by A[j][j]
            // Mapping: A[j][j] in C -> A(j, j) in Halide
            val /= A(j, j);

            // Store back into A[i][j] (i.e. A(j, i) in Halide)
            A(j, i) = val;
        }

        // Second inner loop: j = i .. n-1  (compute U(i,j))
        //
        // These updates are independent across j once row i's L-part
        // has been computed. We therefore compute the entire segment
        // j ∈ [i, n-1] in a single vectorized Halide realization.
        i_param.set(i);

        const int width = n - i;
        if (width > 0) {
            // Lazily allocate a row buffer large enough for the full row
            // (we then restrict its min/extent per iteration to avoid
            // computing unused j < i entries).
            if (!row_buffer.defined() || row_buffer.dim(0).extent() < n) {
                row_buffer = Halide::Buffer<num_t>(n);
            }

            // We only need j in [i, n-1] for this row.
            row_buffer.set_min(i);
            row_buffer.set_extent(0, width);

            // Compute right_row(j) for j ∈ [i, n-1].
            right_row.realize(row_buffer);

            // Copy results back into A[i][j] (A(j, i) in Halide).
            for (int j = i; j < n; j++) {
                A(j, i) = row_buffer(j);
            }
        }
    }

    auto end      = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // -------------------------------------------------------------------------
    // Optional: print the resulting matrix, in the same order as the C version
    // -------------------------------------------------------------------------
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                // A[i][j] in C corresponds to A(j, i) in Halide
                std::cerr << A(j, i) << '\n';
            }
        }
    }

    // Print timing (in seconds)
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
