    // The reduction update is scheduled similarly; parallelizing over
    // pure vars in an update step is safe because each (i,j) element
    // is reduced independently over t.

    Target target = get_host_target();
    const int vec = natural_vector_size<num_t>(target);

    B.compute_root()
        .parallel(i)      // distribute rows across threads
        .vectorize(j, vec);

    B.update()
        .parallel(i)
        .vectorize(j, vec);

    // Realize B directly into the provided buffer A. This is equivalent
    // to computing B and then copying B into A as in the original C code.
    B.realize(A);
}

// -----------------------------------------------------------------------------
// Main
// -----------------------------------------------------------------------------
int main(int argc, char *argv[]) {
    // Problem size
    int n = N;

    // Matrix A: original C is DATA_TYPE A[N][N];
    // We map to Halide Buffer with shape (cols, rows) = (n, n)
    Halide::Buffer<num_t, 2> A(n, n);

    // Initialize A (SPD) with a Halide pipeline.
    init_array(n, A);

    // -------------------------------------------------------------------------
    // Translate kernel_lu into Halide-assisted code.
    //
    // Original C kernel:
    //
    // for (i = 0; i < n; i++) {
    //   for (j = 0; j < i; j++) {
    //     for (k = 0; k < j; k++) {
    //       A[i][j] -= A[i][k] * A[k][j];
    //     }
    //     A[i][j] /= A[j][j];
    //   }
    //   for (j = i; j < n; j++) {
    //     for (k = 0; k < i; k++) {
    //       A[i][j] -= A[i][k] * A[k][j];
    //     }
    //   }
    // }
    //
    // This algorithm has loop-carried dependencies along i and (for the
    // first inner loop) along j, so we cannot express the full kernel
    // as a single pure Halide Func. Instead, we:
    //
    //   - Keep the outer loop over i on the host (as required to
    //     preserve the sequential dependencies between rows).
    //
    //   - For the lower-triangular part (j < i) we keep the scalar
    //     (i, j) computation in Halide: a reduction over k < j.
    //
    //   - For the upper-triangular part (j >= i) there is no j-dependence
    //     inside the k-loop (sum_{k<i} A[i][k] * A[k][j]), so we use
    //     a one-dimensional Halide Func to compute the entire row
    //     segment j = i..n-1 in a single vectorized pipeline call.
    //
    //   - We use an ImageParam bound to the current matrix A and
    //     Param<int> for the current i, j indices.
    // -------------------------------------------------------------------------

    // ImageParam representing the current matrix A; note that we never write
    // to A inside Halide; we only read from it. In-place updates to A are
    // done on the host after each realization. Because ImageParam holds a
    // reference-counted handle to the same underlying buffer, host-side
    // updates are immediately visible to subsequent Halide evaluations.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    A_param.set(A);

    // Scalar parameters for the current (i, j) indices
    Param<int> i_param("i");
    Param<int> j_param("j");

    Target host_target = get_host_target();
    const int vec_k  = natural_vector_size<num_t>(host_target); // for reductions
    const int vec_j  = vec_k;                                   // for row-wise SIMD

    // -------------------------------------------------------------------------
    // Lower-triangular element (L-part): compute
    //   A[i][j] - sum_{k=0}^{j-1} A[i][k] * A[k][j]
    // for j < i, then divide by A[j][j] on the host.
    // -------------------------------------------------------------------------
    Func left_elem("left_elem");
    {
        // A[i][j] in C corresponds to A_param(j_param, i_param)
        left_elem() = A_param(j_param, i_param);

        // Sum over k = 0 .. j-1:
        // A[i][j] -= A[i][k] * A[k][j]
        //
        // A[i][k] -> A_param(k,        i_param)
        // A[k][j] -> A_param(j_param,  k)
        RDom k_left(0, j_param, "k_left");
        left_elem() += cast<num_t>(-1) *
                       A_param(k_left, i_param) *
                       A_param(j_param, k_left);

        // Schedule: scalar reduction, but vectorize the reduction over k
        // when j is large enough. This keeps the semantic order of the
        // for-loop in k but lets the compiler emit SIMD instructions.
        left_elem.compute_root();
        left_elem.update().vectorize(k_left, vec_k);
    }

    // -------------------------------------------------------------------------
    // Upper-triangular row segment (U-part): for fixed i, compute
    //
    //   for (j = i; j < n; j++)
    //     A[i][j] -= sum_{k=0}^{i-1} A[i][k] * A[k][j];
    //
    // There is no loop-carried dependence along j here, so we can
    // compute the whole segment j = i..n-1 in a single 1D pipeline.
    //
    // We index this segment with a relative coordinate jj in [0, n-i):
    //   j_abs = jj + i
    //
    // and compute:
    //
    //   row_u[jj] = A[i][j_abs] - sum_{k=0}^{i-1} A[i][k] * A[k][j_abs]
    // -------------------------------------------------------------------------
    Func u_row("u_row");
    {
        Var jj("jj");  // relative column index: 0 .. (n-i-1)

        Expr j_abs = jj + i_param;  // absolute column index j = i + jj

        // Initial value: A[i][j]
        u_row(jj) = A_param(j_abs, i_param);

        // Reduction over k = 0 .. i-1:
        RDom k_right(0, i_param, "k_right");
        u_row(jj) += cast<num_t>(-1) *
                     A_param(k_right, i_param) *
                     A_param(j_abs, k_right);

        // Schedule: vectorize across jj (columns) so that the pipeline
        // computes several A[i][j] values in parallel. We also vectorize
        // the update step, which results in SIMD-friendly inner loops.
        u_row.compute_root()
             .vectorize(jj, vec_j);

        u_row.update()
             .vectorize(jj, vec_j);
    }

    // JIT-compile the pipelines once; we will reuse them for all (i, j).
    left_elem.compile_jit(host_target);
    u_row.compile_jit(host_target);

    // -------------------------------------------------------------------------
    // Run kernel and time it
    // -------------------------------------------------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    // Temporary buffer reused for scalar left_elem results (0-D Buffer).
    Halide::Buffer<num_t> tmp_left;

    // Temporary 1-D buffer reused for the U-row segment. We allocate it
    // at full length n and crop it per-iteration to avoid repeated
    // heap allocations.
    Halide::Buffer<num_t> u_row_full(n);

    for (int i = 0; i < n; i++) {
        // ---------------------------------------------------------------------
        // First inner loop: j = 0 .. i-1 (lower triangular part, L)
        // ---------------------------------------------------------------------
        for (int j = 0; j < i; j++) {
            i_param.set(i);
            j_param.set(j);

            // Compute A[i][j] - sum_{k<j} A[i][k] * A[k][j]
            left_elem.realize(tmp_left);
            num_t val = tmp_left();  // zero-dimensional buffer

            // Divide by A[j][j]
            // Mapping: A[j][j] in C -> A(j, j) in Halide
            val /= A(j, j);

            // Store back into A[i][j] (i.e. A(j, i) in Halide)
            A(j, i) = val;
        }

        // ---------------------------------------------------------------------
        // Second inner loop: j = i .. n-1 (upper triangular part, U)
        //
        // Here we compute the entire row segment j=i..n-1 in one call
        // to the Halide pipeline u_row, which is vectorized across j.
        // ---------------------------------------------------------------------
        i_param.set(i);

        const int width = n - i;  // number of columns from j=i to j=n-1

        // Create a cropped view of u_row_full that covers indices
        // 0..(width-1); this avoids reallocating memory each iteration.
        Halide::Buffer<num_t> u_row_segment = u_row_full.cropped(0, 0, width);

        // Realize row_u[jj] for jj in [0, width)
        u_row.realize(u_row_segment);

        // Copy the computed values back into A[i][j] for j = i..n-1.
        for (int j = i; j < n; j++) {
            // jj = j - i
            A(j, i) = u_row_segment(j - i);
        }
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // -------------------------------------------------------------------------
    // Optional: print the resulting matrix, in the same order as the C version
    // -------------------------------------------------------------------------
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                // A[i][j] in C corresponds to A(j, i) in Halide
                std::cerr << A(j, i) << '\n';
            }
        }
    }

    // Print timing (in seconds)
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
